/**
 * The Mini Max sound library: the 12 original short SFX, their asset modules, and the
 * per-sound timing that keeps the mix consistent. The audio is generated by
 * mobile/scripts/generate-sounds.py (self-authored, bundled under a CC0-equivalent licence —
 * see mobile/assets/sounds/SOUNDS.md). This file is shared by both engine implementations
 * (engine.native.ts on device, engine.ts on web/tests).
 */

export type SoundName =
  | 'click'
  | 'selection'
  | 'transition'
  | 'close'
  | 'toggle'
  | 'success'
  | 'error'
  | 'warning'
  | 'reward'
  | 'coin'
  | 'unlock'
  | 'notification';

/** The bundled asset for each sound. require() resolves to a native module id or, on web, a URL. */
export const SOUND_SOURCES: Record<SoundName, number> = {
  click: require('../../assets/sounds/click.m4a'),
  selection: require('../../assets/sounds/selection.m4a'),
  transition: require('../../assets/sounds/transition.m4a'),
  close: require('../../assets/sounds/close.m4a'),
  toggle: require('../../assets/sounds/toggle.m4a'),
  success: require('../../assets/sounds/success.m4a'),
  error: require('../../assets/sounds/error.m4a'),
  warning: require('../../assets/sounds/warning.m4a'),
  reward: require('../../assets/sounds/reward.m4a'),
  coin: require('../../assets/sounds/coin.m4a'),
  unlock: require('../../assets/sounds/unlock.m4a'),
  notification: require('../../assets/sounds/notification.m4a'),
};

/**
 * Smallest gap (ms) between two plays of the same sound. A second request inside the window is
 * dropped, so a burst of rapid taps never stacks into a muddy overlap. Everyday ticks debounce
 * harder; deliberate reward/confirmation sounds barely need it.
 */
export const SOUND_DEBOUNCE_MS: Record<SoundName, number> = {
  click: 55,
  selection: 70,
  transition: 90,
  close: 90,
  toggle: 70,
  success: 250,
  error: 250,
  warning: 250,
  reward: 400,
  coin: 120,
  unlock: 300,
  notification: 300,
};

/**
 * Per-sound trim relative to the master volume. The files are already perceptually levelled
 * (clicks quiet, chimes fuller), so these stay near 1; they exist only to fine-tune the blend
 * without regenerating assets.
 */
export const SOUND_TRIM: Record<SoundName, number> = {
  click: 1,
  selection: 1,
  transition: 1,
  close: 1,
  toggle: 1,
  success: 1,
  error: 1,
  warning: 1,
  reward: 1,
  coin: 1,
  unlock: 1,
  notification: 1,
};

export const ALL_SOUNDS = Object.keys(SOUND_SOURCES) as SoundName[];
